  const aliases = Object.freeze({"en":"en","en-us":"en","en-gb":"en","es":"es","pt":"pt-BR","pt-br":"pt-BR","zh":"zh-CN","zh-cn":"zh-CN","zh-hans":"zh-CN","zh-sg":"zh-CN","zh-tw":"zh-TW","zh-hant":"zh-TW","zh-hk":"zh-TW","zh-mo":"zh-TW","ja":"ja","ko":"ko","fr":"fr","de":"de","it":"it","nl":"nl","pl":"pl","tr":"tr","ru":"ru","uk":"uk","hi":"hi","id":"id","vi":"vi","th":"th","ar":"ar","da":"da"});
  let locale = 'en';
